import re
from decimal import Decimal, Context, ROUND_HALF_EVEN

MAX_AMOUNT = Decimal("1000000.00")
_CENT = Decimal("0.01")
# Plain decimal: optional sign, ASCII digits, optional fractional part.
# No whitespace, exponents, underscores, or non-ASCII digits.
_PLAIN_DECIMAL = re.compile(r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)\Z")
# Private context so the global/thread-local decimal context is never touched.
_CTX = Context(prec=50, rounding=ROUND_HALF_EVEN)


def _to_decimal(value):
    if isinstance(value, bool):
        raise ValueError("bool is not a valid amount")
    if isinstance(value, Decimal):
        return value
    if isinstance(value, int):
        return Decimal(value)
    if isinstance(value, str):
        if not _PLAIN_DECIMAL.match(value):
            raise ValueError(f"invalid amount string: {value!r}")
        return Decimal(value)
    raise ValueError(f"unsupported amount type: {type(value).__name__}")


def _to_cents(d):
    """Return d with exponent -2, or raise ValueError if not exact in cents."""
    if d.is_nan() or d.is_infinite():
        raise ValueError("amount must be finite")
    if d > MAX_AMOUNT:
        raise ValueError("amount exceeds 1000000.00")
    quantized = d.quantize(_CENT, context=_CTX)
    if quantized.compare_total(d) != 0 and quantized != d:
        raise ValueError("amount is not exactly representable in cents")
    return quantized


def parse_amount(value):
    d = _to_decimal(value)
    if not d.is_finite():
        raise ValueError("amount must be finite")
    if d.is_zero():
        raise ValueError("amount must be nonzero")
    if d.is_signed():
        raise ValueError("amount must be positive")
    return _to_cents(d)


def format_amount(value):
    return format(value, ".2f")
